void iriap_handle_retrieval(struct iriap_cb *self, struct sk_buff *skb)
{
    char *class_name, *attr_name;
    int class_len, attr_len;
    void *attr_value;

    if (!self || !skb) {
        pr_debug("Invalid parameters in iriap_handle_retrieval.\n");
        return;
    }

    class_name = skb->data;
    class_len = strlen(class_name);
    if (class_len > IRIA_MAX_CLASS_NAME) {
        pr_debug("Class name exceeds maximum length.\n");
        iriap_send_error(skb, IRIA_ERR_INVALID_CLASS_NAME);
        return;
    }

    attr_name = class_name + class_len + 1;
    attr_len = strlen(attr_name);
    if (attr_len > IRIA_MAX_ATTRIBUTE_NAME) {
        pr_debug("Attribute name exceeds maximum length.\n");
        iriap_send_error(skb, IRIA_ERR_INVALID_ATTRIBUTE_NAME);
        return;
    }

    attr_value = iriap_get_attribute(self, class_name, attr_name);
    if (!attr_value) {
        pr_debug("Attribute not found: %s.%s\n", class_name, attr_name);
        iriap_send_error(skb, IRIA_ERR_ATTRIBUTE_NOT_FOUND);
        return;
    }

    pr_debug("Attribute found: %s.%s\n", class_name, attr_name);
    iriap_send_response(skb, IRIA_RSP_SUCCESS, attr_value);
}

void iriap_get_attr_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    char *class_name = NULL, *attr_name = NULL;
    int class_len, attr_len;
    void *attr_value = NULL;
    int error = 0;

    if (!self || !skb) {
        pr_debug("Invalid input parameters in iriap_get_attr_by_class.\n");
        return;
    }

    class_name = skb->data;
    class_len = strlen(class_name);
    attr_name = class_name + class_len + 1;
    attr_len = strlen(attr_name);

    if (class_len > IRIA_MAX_CLASS_NAME || attr_len > IRIA_MAX_ATTR_NAME) {
        pr_debug("Class or attribute name exceeds maximum length.\n");
        iriap_send_error(self, skb, IRIA_ERR_INVALID_NAME);
        return;
    }

    if (!iriap_find_object_by_class(self, class_name)) {
        pr_debug("Object not found for class: %s.\n", class_name);
        iriap_send_error(self, skb, IRIA_ERR_OBJECT_NOT_FOUND);
        return;
    }

    attr_value = iriap_get_attribute_value(self, attr_name);
    if (!attr_value) {
        pr_debug("Attribute not found: %s.\n", attr_name);
        iriap_send_error(self, skb, IRIA_ERR_ATTR_NOT_FOUND);
        return;
    }

    pr_debug("Retrieved attribute value for %s.%s.\n", class_name, attr_name);
    iriap_send_response(self, skb, attr_value, IRIA_SUCCESS);
}

void iriap_getattr_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    char class_name[IAP_MAX_CLASS_NAME_LEN];
    char attr_name[IAP_MAX_ATTR_NAME_LEN];
    int class_len, attr_len;
    struct iap_object *obj;

    if (!self || !skb)
        return;

    /* Extract class and attribute names from socket buffer */
    class_len = skb->data[0];
    if (class_len > IAP_MAX_CLASS_NAME_LEN) {
        netdev_dbg(self->dev, "Class name too long: %d > %d\n", class_len, IAP_MAX_CLASS_NAME_LEN);
        return;
    }
    memcpy(class_name, skb->data + 1, class_len);
    class_name[class_len] = '\0';

    attr_len = skb->data[1 + class_len];
    if (attr_len > IAP_MAX_ATTR_NAME_LEN) {
        netdev_dbg(self->dev, "Attribute name too long: %d > %d\n", attr_len, IAP_MAX_ATTR_NAME_LEN);
        return;
    }
    memcpy(attr_name, skb->data + 1 + class_len + 1, attr_len);
    attr_name[attr_len] = '\0';

    obj = find_iap_object_by_class(self, class_name);
    if (!obj) {
        netdev_dbg(self->dev, "Object for class \"%s\" not found\n", class_name);
        return;
    }

    if (!iap_attr_exists(obj, attr_name)) {
        netdev_dbg(self->dev, "Attribute \"%s\" not found in class \"%s\"\n", attr_name, class_name);
        return;
    }

    netdev_dbg(self->dev, "Retrieving attribute \"%s\" for class \"%s\"\n", attr_name, class_name);
    iap_send_attr_value_response(self, skb, attr_name, obj->attr_values);
}

void handle_class_indication(struct iriap_cb *self, struct sk_buff *skb)
{
    char class_name[IRDA_MAX_CLASS_NAME + 1];
    char attr_name[IRDA_MAX_ATTR_NAME + 1];
    int class_len, attr_len;
    struct iria_object *obj;

    if (!self || !skb)
        return;

    class_len = iria_get_name(skb, class_name, sizeof(class_name));
    if (class_len < 0) {
        iria_send_error(skb, IRIA_ERR_INVALID_CLASS_NAME);
        return;
    }

    attr_len = iria_get_name(skb, attr_name, sizeof(attr_name));
    if (attr_len < 0) {
        iria_send_error(skb, IRIA_ERR_INVALID_ATTR_NAME);
        return;
    }

    obj = iria_find_object(self, class_name);
    if (!obj) {
        iria_send_error(skb, IRIA_ERR_CLASS_NOT_FOUND);
        return;
    }

    if (!iria_has_attribute(obj, attr_name)) {
        iria_send_error(skb, IRIA_ERR_ATTR_NOT_FOUND);
        return;
    }

    iria_get_attribute_value(obj, attr_name, skb);
    iria_send_response(skb, IRIA_RSP_SUCCESS);
}

void iriap_handle_get_attr_by_class(struct iriap_cb *self, struct sk_buff *skb)
{
    int class_len, attr_len;
    u8 *class_name, *attr_name;
    struct sk_buff *resp_skb;

    if (!self || !skb)
        return;

    class_name = skb->data;
    class_len = strlen(class_name);
    if (class_len > IRIA_MAX_CLASS_NAME_LEN)
        return;

    attr_name = class_name + class_len + 1;
    attr_len = strlen(attr_name);
    if (attr_len > IRIA_MAX_ATTR_NAME_LEN)
        return;

    if (!iriap_find_object_by_class(self, class_name)) {
        resp_skb = iriap_build_error_response(skb, IRIA_ERR_NO_SUCH_OBJECT);
        iriap_send_response(self, resp_skb);
        return;
    }

    if (!iriap_find_attribute(self, attr_name)) {
        resp_skb = iriap_build_error_response(skb, IRIA_ERR_NO_SUCH_ATTRIBUTE);
        iriap_send_response(self, resp_skb);
        return;
    }

    resp_skb = iriap_build_success_response(skb, attr_name);
    iriap_send_response(self, resp_skb);
}
